    @Test void archiveMigrationRollbackReapplyPreservesBothParentVersions()throws Exception{
        var schema="task_archive_fixture_"+UUID.randomUUID().toString().replace("-","");var forward=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/migrations/platform/V051__workflow_task_archive.sql")).replace("integration.",schema+".");var reverse=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/rollback/platform/V051__workflow_task_archive.sql")).replace("integration.",schema+".");
        try(var connection=source.getConnection();var statement=connection.createStatement()){
            statement.execute("CREATE SCHEMA "+schema);try{statement.execute("CREATE TABLE "+schema+".workflow_version(tenant_id text,workflow_id text,revision integer,PRIMARY KEY(tenant_id,workflow_id,revision))");statement.execute("INSERT INTO "+schema+".workflow_version VALUES('fixture','archive',1),('fixture','archive',2)");statement.execute(forward);statement.execute(reverse);statement.execute(forward);statement.execute("CREATE TABLE "+schema+".workflow_log_stream_batch(body jsonb)");statement.execute("INSERT INTO "+schema+".workflow_log_stream_batch VALUES('{\"state\":\"FAILED\",\"error\":\"OUTPUT_REJECTED\"}')");var certainty=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/migrations/platform/V052__log_rejection_certainty.sql")).replace("integration.",schema+".");var undoCertainty=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/rollback/platform/V052__log_rejection_certainty.sql")).replace("integration.",schema+".");statement.execute(certainty);try(var evidence=statement.executeQuery("SELECT rejection_known,body->>'state' FROM "+schema+".workflow_log_stream_batch")){assertTrue(evidence.next());assertFalse(evidence.getBoolean(1));assertEquals("FAILED",evidence.getString(2));}statement.execute(undoCertainty);statement.execute(certainty);try(var rows=statement.executeQuery("SELECT count(*) FROM "+schema+".workflow_version")){rows.next();assertEquals(2,rows.getInt(1));}}finally{statement.execute("DROP SCHEMA "+schema+" CASCADE");}
        }
    }
