    @Test void closureMigrationRollbackReapplyIsIsolatedAndPreservesParent()throws Exception{
        var schema="recovery_fixture_"+UUID.randomUUID().toString().replace("-","");var forward=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/migrations/platform/V050__workflow_recovery_closure.sql")).replace("integration.",schema+".");var reverse=java.nio.file.Files.readString(java.nio.file.Path.of("../../db/rollback/platform/V050__workflow_recovery_closure.sql")).replace("integration.",schema+".");
        try(var c=source.getConnection()){c.setAutoCommit(false);try(var q=c.createStatement()){q.execute("CREATE SCHEMA "+schema);q.execute("CREATE TABLE "+schema+".workflow_version(tenant_id text,workflow_id text,revision integer,PRIMARY KEY(tenant_id,workflow_id,revision))");q.execute("INSERT INTO "+schema+".workflow_version VALUES ('fixture','fixed',1)");q.execute(forward);q.execute(reverse);q.execute(forward);try(var r=q.executeQuery("SELECT count(*) FROM "+schema+".workflow_version")){r.next();assertEquals(1,r.getInt(1));}}finally{c.rollback();}}
    }
    @Test void unknownAndOriginalControlSurviveReopeningWithNoImplicitResend(){
        var d=definition();var time=new Time();var sink=new Sink();sink.unknown=true;var service=service(wiring.workflows(),sink,time,(who,src,from,till)->rows(src,from,2));var command=new Command(UUID.randomUUID(),d.id(),1,d.digest(),0,Operation.START);var receipt=service.command(p,command,()->null);time.advance(11);service.tick(p);var unknown=service.status(p,d.id());assertEquals("UNKNOWN",unknown.batches().getFirst().state());assertEquals(0,unknown.task().confirmedWindows());
        var reopened=service(new PostgresWorkflowStore(source),sink,time,(who,src,from,till)->{throw new AssertionError("No source retry");});assertEquals(unknown,reopened.status(p,d.id()));assertEquals(receipt,reopened.command(p,command,()->{throw new AssertionError("No authorization renewal");}));time.advance(60);reopened.tick(p);reopened.verify(p,d.id(),unknown.task().pendingBatchId());assertEquals(1,sink.writes);assertEquals(0,reopened.status(p,d.id()).task().confirmedRecords());sink.visible.put(sink.last.scope().requestId(),sink.last.records());var confirmed=reopened.verify(p,d.id(),unknown.task().pendingBatchId());assertEquals("STOPPED",confirmed.task().state());assertEquals(2,confirmed.task().confirmedRecords());assertEquals(1,sink.writes);assertNull(confirmed.task().pendingBatchId());
        assertFalse(CatalogJson.JSON.writeValueAsString(confirmed).contains("Synthetic Fixture"));assertThrows(IllegalArgumentException.class,()->WorkflowLogStreamJson.batch(CatalogJson.JSON.writeValueAsString(confirmed.batches().getFirst()).replace("\"inputCount\":2","\"inputCount\":\"2\"")));
    }
    @Test void scopeRollbackAndTerminalProofCannotBeRewritten(){
        var d=definition();var time=new Time();var sink=new Sink();var service=service(wiring.workflows(),sink,time,(who,src,from,till)->rows(src,from,2));service.command(p,new Command(UUID.randomUUID(),d.id(),1,d.digest(),0,Operation.START),()->null);time.advance(11);service.tick(p);var proof=service.status(p,d.id()).batches().getFirst();var reopened=new PostgresWorkflowStore(source);
        assertTrue(reopened.transaction(tenant,s->s.logStreamBatch("other",proof.id())).isEmpty());assertTrue(reopened.transaction(new com.acme.opsweave.sharedkernel.TenantId(tenant.value()+"-other"),s->s.logStreamBatch(owner,proof.id())).isEmpty());assertThrows(IllegalStateException.class,()->reopened.transaction(tenant,s->{s.finishLogStreamBatch(owner,proof.finish("UNKNOWN","OUTPUT_UNCONFIRMED",time.instant()));return null;}));
        var copy=new Batch(UUID.randomUUID(),d.id(),1,d.digest(),proof.from(),proof.till(),time.instant(),time.instant(),"IN_FLIGHT",proof.inputCount(),0,0,proof.indices(),proof.positions(),proof.inputDigest(),proof.batchDigest(),null,null);assertThrows(IllegalStateException.class,()->reopened.transaction(tenant,s->{s.addLogStreamBatch(owner,copy);throw new IllegalStateException("Synthetic Fixture rollback");}));assertTrue(reopened.transaction(tenant,s->s.logStreamBatch(owner,copy.id())).isEmpty());assertEquals(proof,reopened.transaction(tenant,s->s.logStreamBatch(owner,proof.id()).orElseThrow()));
    }
    @Test @EnabledIfEnvironmentVariable(named="OPSWEAVE_TEST_LOGS_URL",matches=".+") void thousandRecordsAndLateSupplementUseActualStorageAndReopenedCheckpoint(){
        var d=definition();var time=new Time();var count=new java.util.concurrent.atomic.AtomicInteger(998);var sink=new ClickHouseWorkflowLogWindowSink(URI.create(System.getenv("OPSWEAVE_TEST_LOGS_URL")),System.getenv("OPSWEAVE_TEST_LOGS_USER"),System.getenv("OPSWEAVE_TEST_LOGS_PASSWORD"));assertTrue(sink.ready());WorkflowLogStreamService.Source input=(who,src,from,till)->rows(src,from,count.get());var service=service(wiring.workflows(),sink,time,input);service.command(p,new Command(UUID.randomUUID(),d.id(),1,d.digest(),0,Operation.START),()->null);time.advance(11);service.tick(p);var initial=service.status(p,d.id());assertEquals(998,initial.task().confirmedRecords(),initial.task().error());var original=initial.batches().getFirst();count.set(1000);time.advance(60);service.tick(p);var status=service.status(p,d.id());assertEquals(1000,status.task().confirmedRecords(),status.task().error());assertEquals(1,status.task().confirmedWindows());assertEquals(initial.task().cursor(),status.task().cursor());var supplement=status.batches().getFirst();assertEquals(original.id(),supplement.reconcilesBatchId());assertEquals(998,supplement.deduplicated());assertEquals(List.of(998,999),supplement.indices());assertEquals(2,service.data(p,d.id(),supplement.id()).records().size());
        var reopened=service(new PostgresWorkflowStore(source),sink,time,input);assertEquals(status,reopened.status(p,d.id()));assertTrue(reopened.data(p,d.id(),original.id()).complete());assertEquals(50,reopened.data(p,d.id(),original.id()).records().size());assertEquals(50,reopened.data(p,d.id(),original.id(),49).records().getFirst().index());assertTrue(CatalogJson.JSON.writeValueAsString(supplement).length()>32768);assertFalse(CatalogJson.JSON.writeValueAsString(supplement).contains("Synthetic Fixture"));
        wiring.workflows().transaction(tenant,s->{for(int i=0;i<20;i++){var at=time.instant().plusNanos((i+1)*1000L);var b=new Batch(UUID.randomUUID(),d.id(),1,d.digest(),supplement.from(),supplement.till(),at,at,"IN_FLIGHT",original.inputCount(),0,0,original.indices(),original.positions(),original.inputDigest(),original.batchDigest(),null,null);s.addLogStreamBatch(owner,b);s.finishLogStreamBatch(owner,b.finish("FAILED","OUTPUT_REJECTED",at));}return null;});assertTrue(reopened.status(p,d.id()).batches().stream().noneMatch(b->b.id().equals(supplement.id())));time.advance(1);reopened.tick(p);
        // A successful external write can have an unavailable immediate read. One explicit original
        // verification exercises recovery; it cannot write or silently restart the task.
        var after=reopened.status(p,d.id());if(after.task().pendingBatchId()!=null){var pending=wiring.workflows().transaction(tenant,s->s.logStreamBatch(owner,after.task().pendingBatchId()).orElseThrow());assertEquals("UNKNOWN",pending.state());assertEquals("OUTPUT_UNCONFIRMED",after.task().error());reopened.verify(p,d.id(),pending.id());}
        assertEquals(2,reopened.status(p,d.id()).task().confirmedWindows(),reopened.status(p,d.id()).task().error());assertEquals(2000,reopened.status(p,d.id()).task().confirmedRecords());
    }
